#!/usr/bin/env node
/**
 * Reads the leetcode-progress repo and emits src/data/progress.generated.ts.
 *
 * That repo is a SEPARATE git clone. This script only ever reads from it — it never
 * writes, never stages, never touches its .git. If it is missing, the script exits 0
 * and leaves the previously generated file alone, so `npm run build` still works on
 * Vercel where only this repo is checked out.
 *
 *   node scripts/sync-progress.mjs [path-to-leetcode-progress]
 *
 * Defaults to ../leetcode-progress. Re-run it after you solve things and commit the
 * regenerated file; the data is committed deliberately so the deployed site knows
 * your coverage without needing the other repo present at build time.
 */
import { readFileSync, existsSync, readdirSync, writeFileSync, statSync } from "node:fs";
import { join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = resolve(HERE, "../src/data/progress.generated.ts");
const SRC = resolve(process.argv[2] ?? join(HERE, "../../leetcode-progress"));
const REPO = "https://github.com/RaghhavMalani/leetcode-progress";

if (!existsSync(SRC) || !statSync(SRC).isDirectory()) {
  console.log(`[sync-progress] ${SRC} not found — keeping the committed data as is.`);
  process.exit(0);
}

/* The header line of every NOTES.md looks like:
 *   > **Hard** &nbsp;&middot;&nbsp; Two pointers · converging &nbsp;&middot;&nbsp; family: **Two pointers & sliding window**
 *
 * The middle dot appears in that file BOTH as the HTML entity `&middot;` (as the field
 * separator) and as a literal U+00B7 (inside the pattern label itself), and which form
 * the separator uses has already changed once under me. So the separator pattern accepts
 * the entity, the numeric reference and the literal character, and tolerates CRLF. A
 * parser that silently yields zero families is worse than one that throws, so the caller
 * checks the hit rate and fails loudly. */
const SEP = String.raw`\s*(?:&nbsp;)?\s*(?:&middot;|&#183;|·)\s*(?:&nbsp;)?\s*`;
const HEAD = new RegExp(
  String.raw`>\s*\*\*(\w+)\*\*` + SEP + String.raw`(.*?)` + SEP + String.raw`family:\s*\*\*(.*?)\*\*`,
);
const DIFF_ONLY = />\s*\*\*(\w+)\*\*/;

const entries = [];
let withNotes = 0;
let withViz = 0;

for (const dir of readdirSync(SRC).sort()) {
  const full = join(SRC, dir);
  if (!statSync(full).isDirectory() || !/^\d{4}-/.test(dir)) continue;

  const num = parseInt(dir.slice(0, 4), 10);
  const notes = join(full, "NOTES.md");
  let diff = "";
  let label = "";
  let family = "";

  if (existsSync(notes)) {
    const text = readFileSync(notes, "utf8");
    const m = HEAD.exec(text);
    if (m) {
      [, diff, label, family] = m;
      withNotes++;
    } else {
      const d = DIFF_ONLY.exec(text);
      if (d) diff = d[1];
    }
  }

  const langs = readdirSync(full)
    .map((f) => (/\.(py|cpp|java|js|c)$/.exec(f) ?? [])[1])
    .filter(Boolean)
    .sort();

  const viz = existsSync(join(SRC, "visualizations", `${dir}.html`));
  if (viz) withViz++;

  entries.push({
    num,
    dir,
    diff: diff.toLowerCase(),
    label,
    family,
    langs: [...new Set(langs)],
    viz,
    notes: existsSync(notes),
  });
}

/* stats.json is LeetHub's own tally. We prefer our own count of directories, but we
 * read theirs so a mismatch is visible rather than silent. */
let declared = null;
const statsPath = join(SRC, "stats.json");
if (existsSync(statsPath)) {
  try {
    const s = JSON.parse(readFileSync(statsPath, "utf8"));
    if (s.leetcode) {
      declared = {
        solved: s.leetcode.solved ?? null,
        easy: s.leetcode.easy ?? null,
        medium: s.leetcode.medium ?? null,
        hard: s.leetcode.hard ?? null,
      };
    }
  } catch {
    /* malformed stats.json is not fatal — the directory scan is the source of truth */
  }
}

const counted = { easy: 0, medium: 0, hard: 0 };
for (const e of entries) if (e.diff in counted) counted[e.diff]++;

/* Fail loudly rather than emitting a snapshot with every family blank. A silent parse
 * failure here degrades the whole coverage view into "no adjacent work anywhere", which
 * looks like data rather than like a bug. */
const withHeaders = entries.filter((e) => e.notes).length;
if (withHeaders > 0 && withNotes < withHeaders * 0.5) {
  console.error(
    `[sync-progress] ABORT: parsed a family header from only ${withNotes} of ${withHeaders} ` +
      `NOTES.md files. The header format has probably changed — fix the HEAD regex rather ` +
      `than committing a snapshot with blank families.`,
  );
  process.exit(1);
}

const esc = (s) => String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
const row = (e) =>
  `  { num: ${e.num}, dir: "${esc(e.dir)}", diff: "${esc(e.diff)}", label: "${esc(e.label)}", ` +
  `family: "${esc(e.family)}", langs: [${e.langs.map((l) => `"${l}"`).join(", ")}], ` +
  `viz: ${e.viz}, notes: ${e.notes} },`;

const out = `/* GENERATED by scripts/sync-progress.mjs — do not edit by hand.
 *
 * Source: ${REPO}
 * Scanned ${entries.length} problem directories; ${withNotes} carry a parsed NOTES.md
 * header and ${withViz} have a traced visualisation.
 *
 * Committed on purpose: the deployed site has no access to the other repo, so this
 * snapshot is what it reads. Re-run the script and commit after you solve things.
 */

export interface SolvedEntry {
  /** LeetCode problem number */
  num: number;
  /** directory name in the progress repo, e.g. "0042-trapping-rain-water" */
  dir: string;
  /** "easy" | "medium" | "hard", or "" if NOTES.md had no header */
  diff: string;
  /** the author's own fine-grained pattern label, e.g. "Two pointers · converging" */
  label: string;
  /** one of the 16 families used in that repo's PATTERNS.md */
  family: string;
  /** which languages the solution exists in */
  langs: readonly string[];
  /** a step-by-step traced HTML visualisation exists */
  viz: boolean;
  /** a written NOTES.md exists */
  notes: boolean;
}

export const PROGRESS_REPO = "${REPO}";

/** Counted by scanning directories, not taken on trust from stats.json. */
export const PROGRESS_COUNTS = {
  total: ${entries.length},
  easy: ${counted.easy},
  medium: ${counted.medium},
  hard: ${counted.hard},
  withNotes: ${withNotes},
  withViz: ${withViz},
} as const;

/** What stats.json claims, for comparison. Null when absent or unparseable. */
export const PROGRESS_DECLARED = ${declared ? JSON.stringify(declared) : "null"} as const;

export const SOLVED: readonly SolvedEntry[] = [
${entries.map(row).join("\n")}
];
`;

writeFileSync(OUT, out, "utf8");
console.log(
  `[sync-progress] ${entries.length} problems ` +
    `(${counted.easy}E / ${counted.medium}M / ${counted.hard}H), ` +
    `${withNotes} with notes, ${withViz} with traces → src/data/progress.generated.ts`,
);
if (declared && declared.solved !== null && declared.solved !== entries.length) {
  console.log(
    `[sync-progress] note: stats.json says ${declared.solved} solved, directories say ${entries.length}. ` +
      `Using the directory count.`,
  );
}
